def throttle(period, max_calls=1):
    """Decorator that limits function calls to max_calls per time period."""
    if isinstance(period, (int, float)):
        period = timedelta(seconds=period)

    def decorator(func):
        calls = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = datetime.now()
            # Remove old calls outside the period window
            while calls and now - calls[0] > period:
                calls.pop(0)
            if len(calls) >= max_calls:
                raise ErrorRateExceeded("Rate limit exceeded")
            calls.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator


@decorator
def process_beat(call, period, max_calls=1):
    """Ensures the decorated function runs at most max_calls per period."""
    if not hasattr(call._func, '_last_calls'):
        call._func._last_calls = []

    now = datetime.now()
    if isinstance(period, (int, float)):
        period = timedelta(seconds=period)

    # Clean old entries
    while call._func._last_calls and now - call._func._last_calls[0] > period:
        call._func._last_calls.pop(0)

    if len(call._func._last_calls) >= max_calls:
        raise ErrorRateExceeded("Beat rate exceeded")
    call._func._last_calls.append(now)
    return call()


